/**
 * ==========================================================================================
 * COMPOSANT : CameraRecognition.jsx
 * VERSION FINALE : 5.0.0 (Correction Flux Vidéo Noir & Force Play)
 * DESCRIPTION : Système de pointage biométrique haute performance.
 * ==========================================================================================
 */

import React, { useState, useRef, useEffect, useCallback, useMemo } from 'react';
import { attendanceAPI, studentsAPI } from './api_service';

// ==========================================================================================
// CONFIGURATION DU SYSTÈME & THÈME VISUEL
// ==========================================================================================
const THEME = {
    colors: {
        primary: '#6366F1',
        primaryDark: '#4338CA',
        primaryLight: '#EEF2FF',
        success: '#10B981',
        successDark: '#059669',
        danger: '#EF4444',
        dangerDark: '#B91C1C',
        warning: '#F59E0B',
        textMain: '#0F172A',
        textMuted: '#64748B',
        border: '#E2E8F0',
        background: '#F8FAFC',
        surface: '#FFFFFF',
        overlay: 'rgba(0, 0, 0, 0.8)'
    },
    shadows: {
        card: '0 10px 25px -5px rgba(0, 0, 0, 0.1), 0 8px 10px -6px rgba(0, 0, 0, 0.1)',
        inner: 'inset 0 2px 4px 0 rgba(0, 0, 0, 0.06)'
    }
};

const SCAN_CONFIG = {
    DURATION_MS: 10000,
    API_INTERVAL_MS: 650,
    UI_REFRESH_MS: 50,
    MIN_CONFIDENCE: 0.45,
    CONSTRAINTS: {
        video: {
            width: { ideal: 1280 },
            height: { ideal: 720 },
            facingMode: "user",
            frameRate: { ideal: 30 }
        },
        audio: false
    }
};

// ==========================================================================================
// COMPOSANTS UI DE SOUTIEN
// ==========================================================================================

const BadgeStatus = ({ active, scanning }) => (
    <div style={{
        ...styles.badge,
        backgroundColor: scanning ? THEME.colors.warning : (active ? THEME.colors.success : THEME.colors.danger)
    }}>
        <div style={styles.pulseDot} />
        {scanning ? 'SCAN EN COURS...' : (active ? 'CAMÉRA ACTIVE' : 'SYSTÈME HORS-LIGNE')}
    </div>
);

const InfoRow = ({ label, value, bold }) => (
    <div style={styles.infoRow}>
        <span style={styles.infoLabel}>{label}</span>
        <span style={{ ...styles.infoValue, fontWeight: bold ? '700' : '400', color: bold ? THEME.colors.primary : THEME.colors.textMain }}>
            {value}
        </span>
    </div>
);

// ==========================================================================================
// COMPOSANT PRINCIPAL : CAMERA RECOGNITION
// ==========================================================================================
const CameraRecognition = ({ addNotification }) => {
    // --- REFS ---
    const videoRef = useRef(null);
    const streamRef = useRef(null);
    const canvasRef = useRef(null);
    const scanIntervalRef = useRef(null);
    const scanTimeoutRef = useRef(null);
    const progressIntervalRef = useRef(null);

    // --- STATES ---
    const [isCameraActive, setIsCameraActive] = useState(false);
    const [isVideoLoaded, setIsVideoLoaded] = useState(false);
    const [isDetecting, setIsDetecting] = useState(false);
    const [isLoading, setIsLoading] = useState(false);
    const [scanProgress, setScanProgress] = useState(0);
    const [error, setError] = useState(null);
    const [result, setResult] = useState(null);
    const [photos, setPhotos] = useState({ captured: null, reference: null });

    // ======================================================================================
    // ✅ CORRECTION 3 : EFFECT DE FORCE BINDING
    // ======================================================================================
    useEffect(() => {
        if (isCameraActive && videoRef.current && streamRef.current) {
            console.log("[Fix] Re-binding stream to video element...");
            videoRef.current.srcObject = streamRef.current;

            videoRef.current.play().catch(err => {
                console.warn("[Fix] Retry play failed:", err);
            });
        }
    }, [isCameraActive]);

    /**
     * Nettoyage complet des ressources
     */
    const stopAll = useCallback(() => {
        if (scanIntervalRef.current) clearInterval(scanIntervalRef.current);
        if (scanTimeoutRef.current) clearTimeout(scanTimeoutRef.current);
        if (progressIntervalRef.current) clearInterval(progressIntervalRef.current);

        if (streamRef.current) {
            streamRef.current.getTracks().forEach(track => track.stop());
            streamRef.current = null;
        }

        if (videoRef.current) videoRef.current.srcObject = null;

        setIsCameraActive(false);
        setIsVideoLoaded(false);
        setIsDetecting(false);
        setScanProgress(0);
    }, []);

    // ======================================================================================
    // ✅ CORRECTION 1 & 2 : BOOT CAMERA ROBUSTE
    // ======================================================================================
    const bootCamera = async () => {
        console.log("[System] Initialisation...");
        setError(null);
        setIsLoading(true);

        try {
            stopAll(); // Reset préalable

            const stream = await navigator.mediaDevices.getUserMedia(SCAN_CONFIG.CONSTRAINTS);
            streamRef.current = stream;

            if (videoRef.current) {
                // Configuration des attributs critiques pour le web mobile/Safari
                videoRef.current.muted = true;
                videoRef.current.playsInline = true;
                videoRef.current.srcObject = stream;

                // ✅ CORRECTION : Play immédiat sans attendre onloadedmetadata
                videoRef.current.play()
                    .then(() => {
                        console.log("[Video] Flux démarré avec succès.");
                        setIsVideoLoaded(true);
                        setIsCameraActive(true);
                        setIsLoading(false);
                    })
                    .catch(playErr => {
                        console.error("[Video] Erreur de lecture forcée:", playErr);
                        setError("Le navigateur bloque la vidéo. Cliquez à nouveau.");
                        setIsLoading(false);
                    });

                // Support secondaire
                videoRef.current.onloadedmetadata = () => {
                    console.log("[Video] Metadonnées chargées.");
                };
            }
        } catch (err) {
            console.error("[Fatal] Erreur accès média:", err);
            setError(err.name === 'NotAllowedError' ? "Permission refusée" : "Erreur caméra");
            setIsLoading(false);
        }
    };

    /**
     * Capture d'image depuis le flux
     */
    const captureFrame = useCallback(() => {
        if (!videoRef.current || !isVideoLoaded) return null;

        if (!canvasRef.current) canvasRef.current = document.createElement('canvas');
        const canvas = canvasRef.current;
        const video = videoRef.current;

        canvas.width = video.videoWidth;
        canvas.height = video.videoHeight;
        const ctx = canvas.getContext('2d');

        // Miroir
        ctx.translate(canvas.width, 0);
        ctx.scale(-1, 1);
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);

        return canvas.toDataURL('image/jpeg', 0.8);
    }, [isVideoLoaded]);

    /**
     * Traitement de la réussite
     */
    const handleSuccess = async (data, img) => {
        setPhotos(prev => ({ ...prev, captured: img }));
        setResult({
            name: data.student,
            conf: (data.confidence * 100).toFixed(1),
            id: data.attendance_id || 'ID-' + Date.now().toString(36),
            time: new Date().toLocaleTimeString()
        });

        if (data.student_id) {
            try {
                const res = await studentsAPI.getById(data.student_id);
                if (res?.data?.photo_url) setPhotos(prev => ({ ...prev, reference: res.data.photo_url }));
            } catch (e) { console.warn("Photo profil absente"); }
        }

        setIsDetecting(false);
        addNotification?.(`Entrée validée : ${data.student}`, 'success');
    };

    /**
     * Cycle de détection 10 secondes
     */
    const runScanCycle = () => {
        if (!isCameraActive || isDetecting) return;

        setIsDetecting(true);
        setScanProgress(0);
        setResult(null);
        setPhotos({ captured: null, reference: null });

        let best = null;
        const start = Date.now();

        scanIntervalRef.current = setInterval(async () => {
            const frame = captureFrame();
            if (!frame) return;

            try {
                const res = await attendanceAPI.recognize(frame);
                if (res?.data?.success && res.data.confidence > SCAN_CONFIG.MIN_CONFIDENCE) {
                    if (!best || res.data.confidence > best.confidence) {
                        best = { ...res.data, frame };
                    }
                }
            } catch (e) {}
        }, SCAN_CONFIG.API_INTERVAL_MS);

        progressIntervalRef.current = setInterval(() => {
            const diff = Date.now() - start;
            setScanProgress(Math.min(100, (diff / SCAN_CONFIG.DURATION_MS) * 100));
        }, 50);

        scanTimeoutRef.current = setTimeout(() => {
            clearInterval(scanIntervalRef.current);
            clearInterval(progressIntervalRef.current);
            if (best) handleSuccess(best, best.frame);
            else {
                setIsDetecting(false);
                setError("Échec de l'identification : aucun visage reconnu.");
            }
        }, SCAN_CONFIG.DURATION_MS);
    };

    /**
     * Nettoyage au démontage
     */
    useEffect(() => { return () => stopAll(); }, [stopAll]);

    // ======================================================================================
    // RENDU
    // ======================================================================================

    return (
        <div style={styles.page}>
            {/* HEADER */}
            <header style={styles.nav}>
                <div style={styles.brand}>
                    <div style={styles.logo}>⚡</div>
                    <div>
                        <h1 style={styles.navTitle}>Biometric Gate</h1>
                        <p style={styles.navSub}>v5.0 Stable Release</p>
                    </div>
                </div>
                <div style={styles.meta}>
                    Statut : <span style={{ color: isCameraActive ? THEME.colors.success : THEME.colors.danger, fontWeight: 700 }}>
                        {isCameraActive ? 'ONLINE' : 'OFFLINE'}
                    </span>
                </div>
            </header>

            <main style={styles.grid}>
                {/* ZONE CAMERA */}
                <section style={styles.card}>
                    <div style={styles.viewer}>
                        {isCameraActive ? (
                            <video ref={videoRef} autoPlay playsInline muted style={styles.video} />
                        ) : (
                            <div style={styles.placeholder} onClick={bootCamera}>
                                <span style={{ fontSize: '3rem' }}>📸</span>
                                <p>Cliquez pour activer la caméra</p>
                                <button style={styles.btnMain}>ACTIVER MAINTENANT</button>
                            </div>
                        )}

                        {isCameraActive && <BadgeStatus active={isCameraActive} scanning={isDetecting} />}
                        {isDetecting && <div style={styles.scannerLine} />}

                        {isDetecting && (
                            <div style={styles.progressLabel}>{Math.round(scanProgress)}%</div>
                        )}
                    </div>

                    <div style={styles.progressBar}>
                        <div style={{ ...styles.progressFill, width: `${scanProgress}%` }} />
                    </div>

                    <div style={styles.actions}>
                        {!isCameraActive ? (
                            <button onClick={bootCamera} style={styles.btnFull}>DÉMARRER LE SYSTÈME</button>
                        ) : (
                            <div style={styles.btnGroup}>
                                <button 
                                    onClick={runScanCycle} 
                                    disabled={isDetecting} 
                                    style={{ ...styles.btnBase, background: THEME.colors.primary }}
                                >
                                    {isDetecting ? 'ANALYSE...' : 'DÉMARRER LE SCAN (10s)'}
                                </button>
                                <button 
                                    onClick={stopAll} 
                                    style={{ ...styles.btnBase, background: THEME.colors.danger }}
                                >
                                    ARRÊTER
                                </button>
                            </div>
                        )}
                    </div>

                    {error && (
                        <div style={styles.errorBox}>
                            <strong>ERREUR :</strong> {error}
                        </div>
                    )}
                </section>

                {/* ZONE RÉSULTATS */}
                <aside style={styles.sidebar}>
                    {result ? (
                        <div style={styles.resCard}>
                            <h2 style={styles.resTitle}>Résultat d'Analyse</h2>
                            <div style={styles.photoGrid}>
                                <div style={styles.photoBox}>
                                    <span style={styles.photoTag}>Capture</span>
                                    <img src={photos.captured} style={styles.img} alt="Live" />
                                </div>
                                <div style={styles.photoBox}>
                                    <span style={styles.photoTag}>Dossier</span>
                                    {photos.reference ? (
                                        <img src={photos.reference} style={styles.img} alt="Ref" />
                                    ) : (
                                        <div style={styles.noImg}>N/A</div>
                                    )}
                                </div>
                            </div>

                            <div style={styles.dataList}>
                                <InfoRow label="Identité" value={result.name} bold />
                                <InfoRow label="Confiance" value={`${result.conf}%`} bold />
                                <InfoRow label="ID Trace" value={result.id} />
                                <InfoRow label="Horodatage" value={result.time} />
                            </div>

                            <button onClick={() => setResult(null)} style={styles.btnReset}>NOUVELLE CAPTURE</button>
                        </div>
                    ) : (
                        <div style={styles.empty}>
                            <p>En attente d'identification...</p>
                            <small>Lancez un scan pour voir les détails de l'étudiant</small>
                        </div>
                    )}
                </aside>
            </main>

            <footer style={styles.footer}>
                © 2026 Biometric System Integration — All Rights Reserved
            </footer>

            <style dangerouslySetInnerHTML={{ __html: `
                @keyframes scanner { 
                    0% { top: 0%; opacity: 0; } 
                    50% { opacity: 1; }
                    100% { top: 100%; opacity: 0; } 
                }
                button:hover { filter: brightness(1.1); transform: translateY(-1px); }
                button:active { transform: translateY(0); }
            ` }} />
        </div>
    );
};

// ==========================================================================================
// STYLES DÉTAILLÉS
// ==========================================================================================
const styles = {
    page: { 
        minHeight: '100vh', backgroundColor: THEME.colors.background, 
        padding: '20px', fontFamily: 'system-ui, sans-serif' 
    },
    nav: { 
        display: 'flex', justifyContent: 'space-between', alignItems: 'center',
        padding: '15px 25px', backgroundColor: THEME.colors.surface, 
        borderRadius: '15px', marginBottom: '20px', boxShadow: THEME.shadows.card 
