    grid: { display: 'grid', gridTemplateColumns: '1fr 380px', gap: '20px' },
    card: { 
        backgroundColor: THEME.colors.surface, borderRadius: '25px', 
        padding: '25px', boxShadow: THEME.shadows.card, display: 'flex', flexDirection: 'column', gap: '20px' 
