        alignItems: 'center', justifyContent: 'center', gap: '15px', color: THEME.colors.textMuted, cursor: 'pointer' 
    },
    badge: { 
        position: 'absolute', top: '15px', right: '15px', padding: '8px 15px', 
        borderRadius: '30px', color: '#fff', fontSize: '0.7rem', fontWeight: 'bold', 
        display: 'flex', alignItems: 'center', gap: '8px', zIndex: 10 
    },
    pulseDot: { 
        width: '8px', height: '8px', background: '#fff', borderRadius: '50%', 
        animation: 'pulse 1.5s infinite' 
    },
    scannerLine: { 
        position: 'absolute', left: 0, width: '100%', height: '3px', 
