        color: '#991B1B', borderRadius: '8px', fontSize: '0.9rem' 
    },
    sidebar: { display: 'flex', flexDirection: 'column', gap: '20px' },
    resCard: { 
        background: '#fff', borderRadius: '25px', padding: '25px', 
        boxShadow: THEME.shadows.card, animation: 'slideIn 0.3s ease-out' 
    },
    photoGrid: { display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '15px', marginBottom: '20px' },
    photoBox: { textAlign: 'center' },
    photoTag: { fontSize: '0.6rem', textTransform: 'uppercase', color: THEME.colors.textMuted, display: 'block', marginBottom: '5px' },
    img: { width: '100%', aspectRatio: '1/1', objectFit: 'cover', borderRadius: '12px', border: '2px solid ' + THEME.colors.border },
